 "content": "from functools import lru_cache


def transform(grid):
    """Tile the nonzero shape with 2x2 squares and oriented L triominoes.

    Squares become color 1. L triominoes are colored 2-5 according to
    the missing corner of their 2x2 bounding box.
    """
    h, w = len(grid), len(grid[0])
    cells = frozenset(
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] != 0
    )

    candidates = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if block <= cells:
                candidates.append((frozenset(block), 1))
            # Missing top-left, bottom-left, top-right, bottom-right.
            for missing, color in (
                ((r, c), 2),
                ((r + 1, c), 3),
                ((r, c + 1), 4),
                ((r + 1, c + 1), 5),
            ):
                piece = block - {missing}
                if piece <= cells:
                    candidates.append((frozenset(piece), color))

    by_cell = {
        cell: [i for i, (piece, _) in enumerate(candidates) if cell in piece]
        for cell in cells
    }

    @lru_cache(None)
    def tile(remaining):
        if not remaining:
            return ()
        cell = min(
            remaining,
            key=lambda p: sum(candidates[i][0] <= remaining for i in by_cell[p]),
        )
        for i in by_cell[cell]:
            piece, color = candidates[i]
            if piece <= remaining:
                rest = tile(frozenset(remaining - piece))
                if rest is not None:
                    return ((piece, color),) + rest
        return None

    pieces = tile(cells)
    if pieces is None:
        raise ValueError("Nonzero cells cannot be tiled by 2x2 squares and L triominoes")

    output = [[0] * w for _ in range(h)]
    for piece, color in pieces:
        for r, c in piece:
            output[r][c] = color
    return output


